import pytest
from unittest.mock import MagicMock
from echo_sync.cm_answer import AnswerMixin

class MockAnswer(AnswerMixin):
    def state(self):
        return {'history': ()}
    def public_lookup_allowed(self, asked):
        return True

def test_remark_not_routed():
    obj = MockAnswer()
    obj.fast_call = True
    # "ну ты опять путаешь" should be a remark (objection).
    # If remark_ruling returns None, _fast_routed returns True.
    asked = "ну ты опять путаешь"
    assert obj._fast_routed(asked) is False
